type official =
  | Secretary
  | Other_official of string

type officer = {
  officer_department_or_agency : official;
  duly_authorized_directly : bool;
  duly_authorized_by_redelegation : bool;
}

let refers_to_secretary (ref_official : official) : bool =
  match ref_official with
  | Secretary -> true
  | Other_official _ -> false

(* 7701(a)(12)(A)(i) *)
let meaning_of_delegate_secretary (ref_official : official) (o : officer) : bool =
  o.officer_department_or_agency = ref_official &&
  (o.duly_authorized_directly || o.duly_authorized_by_redelegation)

(* 7701(a)(12)(A)(ii) - similarly construed as (i) *)
let meaning_of_delegate_other (ref_official : official) (o : officer) : bool =
  o.officer_department_or_agency = ref_official &&
  (o.duly_authorized_directly || o.duly_authorized_by_redelegation)

let meaning_of_delegate (ref_official : official) (o : officer) : bool =
  if refers_to_secretary ref_official then meaning_of_delegate_secretary ref_official o
  else meaning_of_delegate_other ref_official o
